code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A horizontal 5-bar copies the color marker below it across its length.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == 5:
                c += 1
            end = c
            if r + 1 < h and grid[r+1][start] not in (0, 5):
                for rr in range(r+1, h):
                    color = grid[rr][start]
                    if color in (0, 5):
                        break
                    for cc in range(start, end):
                        out[rr][cc] = color
    # A vertical 5-bar copies the adjacent right-side motif along its length.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] == 5:
                r += 1
            end = r
            seed = [rr for rr in range(start, end) if c+1 < w and grid[rr][c+1] not in (0, 5)]
            if not seed:
                continue
            width = 0
            while c+1+width < w and grid[seed[0]][c+1+width] not in (0, 5):
                width += 1
            if width == 0:
                continue
            for rr in range(start, end):
                src = seed[(rr-start) % len(seed)]
                for offset in range(width):
                    if grid[src][c+1+offset] not in (0, 5):
                        out[rr][c+1+offset] = grid[src][c+1+offset]
    return out
